from pathlib import Path
import json,re,html,base64,sys
sys.stdout.reconfigure(encoding='utf-8',errors='replace')
root=Path(__file__).resolve().parents[1];out=root/'output';destination=out/'report/第二阶段文献库交付报告.html'
def read(name):return json.loads((out/name).read_text(encoding='utf-8'))
def cli(name):
    text=(out/name).read_text(encoding='utf-8-sig')
    return json.loads(text.split('### Result',1)[1].split('### Ran Playwright code',1)[0].strip())
def image(name):return 'data:image/png;base64,'+base64.b64encode((out/name).read_bytes()).decode('ascii')
def esc(value):return html.escape(str(value))
flow=cli('stage2-ui-flow.log');safety=cli('stage2-ui-safety.log');draft=cli('stage2-draft-isolation.log');reader=cli('stage2-reader-regression.log')
first=cli('stage2-ui-import-first.log');duplicate=cli('stage2-ui-import-duplicate.log');directory=cli('stage2-ui-directory.log');upgrade=read('stage2-primary-upgrade.json')
testlog=(out/'stage2-tests-final.log').read_text(encoding='utf-8-sig');tests=int(re.search(r'ℹ tests (\d+)',testlog).group(1));passed=int(re.search(r'ℹ pass (\d+)',testlog).group(1))
assert tests==passed and all(x['passed'] for x in flow['checks']+safety['results']) and draft['passed'] and reader['metadataIndependent']
assert first['items']==first['baseline']['items']+1 and duplicate['items']==first['items'] and duplicate['files']==first['files']
assert '已忽略 1' in directory['notice'] and all(x['unchanged'] for x in upgrade['records']) and upgrade['filesChecked']==upgrade['filesUnchanged']
for name,value in [('stage2-ui-flow',flow),('stage2-ui-safety',safety),('stage2-draft-isolation',draft),('stage2-reader-regression',reader),('stage2-ui-directory',directory)]:
    (out/(name+'.json')).write_text(json.dumps(value,ensure_ascii=False,indent=2),encoding='utf-8')
summary={'version':'0.2.0-local-library','schemaVersion':2,'unitTests':tests,'unitPassed':passed,'mainUiChecks':len(flow['checks']),'safetyUiChecks':len(safety['results']),
    'draftIsolation':True,'fileImportAndDeduplication':True,'directoryExclusions':True,'readerRegression':True,'primaryDataPreserved':upgrade['records'],'filesVerified':upgrade['filesUnchanged'],
    'backupPath':upgrade['migration']['backupPath'],'delivery':'local browser application; desktop package and writing-tool plugin remain future work'}
(out/'phase-2-summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2),encoding='utf-8')
previous=(out/'report/第一阶段技术验证结果.html').read_text(encoding='utf-8');style=re.search(r'<style>(.*?)</style>',previous,re.S).group(1)
labels={'library_items':'文献条目','attachments':'附件关联','annotation_documents':'标注修订记录','annotations':'标注','reading_states':'阅读位置 / 视图','exports':'历史导出'}
rows=''.join('<tr><td>'+labels[row['table']]+'</td><td>'+str(row['before'])+'</td><td>'+str(row['after'])+'</td><td class="pass">内容摘要一致</td></tr>' for row in upgrade['records'])
body='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="data:,"><title>第二阶段交付报告 · 本地文献工作台</title><style>@@STYLE@@ .cta{display:inline-block;background:var(--green);color:white;padding:11px 18px;border-radius:8px;text-decoration:none;font-size:14px;margin:22px 10px 0 0}.cta.secondary{background:var(--paper);color:var(--green);border:1px solid var(--line)}.feature-list{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.feature-list article{padding:23px;background:var(--paper);border:1px solid var(--line);border-radius:12px}.feature-list h3{font-size:16px}.feature-list p{font-size:13px;color:var(--muted);margin-top:10px}.steps{padding-left:22px;line-height:2.1;font-size:14px}.status-strip{padding:18px 22px;border-radius:10px;background:var(--soft);font-size:14px;margin-top:22px}@media(max-width:800px){.feature-list{grid-template-columns:1fr}}@media print{.cta{display:none}.feature-list article{break-inside:avoid}}</style></head><body><main class="page"><header><span>本地文献工作台 / 第二阶段交付报告</span><span class="badge">v0.2 · 2026.10.30</span></header>
<div class="hero"><div class="eyebrow">PHASE 02 / PERSONAL LIBRARY</div><h1>找到论文，整理信息。<br><span>让阅读接上文献库。</span></h1><p class="lead">第二阶段已完成文献库界面、元数据编辑与规范化、组合检索、智能集合、导入和批量整理，并接回已经验证的独立 PDF 阅读页面。</p><p class="scope">你的主资料库已升级到 schema 2，升级前自动备份。测试使用隔离副本，带“第二阶段界面验收”等前缀的条目没有写入主库。当前交付仍是本机浏览器应用，桌面安装包与 Word/WPS 引用插件留待后续。</p><a class="cta" href="http://127.0.0.1:4178/">打开本地文献工作台 ↗</a><a class="cta secondary" href="../../README.md">使用与启动说明</a></div>
<div class="metrics"><div class="metric"><strong>34</strong><span>既有文献与附件完整保留</span><small>原有 ID 与关联关系不变</small></div><div class="metric"><strong>102</strong><span>既有标注逐表核对一致</span><small>阅读位置与历史导出同样保留</small></div><div class="metric"><strong>@@TESTS@@ / @@TESTS@@</strong><span>自动化基础测试通过</span><small>迁移、检索、导入和数据保护</small></div><div class="metric"><strong>20 + 5</strong><span>界面流程与专项验证</span><small>真实操作，不以静态界面代替功能</small></div></div>
<nav><a href="#features">可用功能</a><a href="#screens">实际界面</a><a href="#data">数据保留</a><a href="#quality">可靠性验证</a><a href="#extension">扩展与下一步</a></nav>
<section id="features"><h2>这一版已经可以做什么</h2><div class="feature-list"><article><h3>编辑完整书目信息</h3><p>题名、文献类型、有序作者、年份、卷期日期、网络首发日期、期刊、DOI、卷期页码与摘要。作者可填写完整姓名，也可按姓与名结构化保存。</p></article><article><h3>多维组合检索</h3><p>作者、年份范围、期刊、标签、阅读与核对状态可以同时筛选。不同维度取交集，作者和标签可选择“任一”或“全部”。缺失信息有独立入口。</p></article><article><h3>智能集合与期刊归一</h3><p>保存常用条件，新导入或修改后匹配的论文自动出现。期刊缩写与不同拼写可以归入标准名称，原始字段仍保留。</p></article><article><h3>批量整理与回收站</h3><p>勾选条目后统一设置状态、期刊、年份和标签。批量操作使用事务；移入回收站保留 PDF 与标注，支持恢复。</p></article><article><h3>PDF 导入与内容去重</h3><p>支持单个、多选、拖放及文件夹导入，复制文件后按哈希去重。目录导入会忽略程序自己的资料库、导出、依赖和缓存目录。</p></article><article><h3>可核对的 DOI 候选</h3><p>手动查询 Crossref，先比较当前信息与候选值，再选择字段应用到草稿。不会自动保存，不上传 PDF，断网时仍能继续本地整理。</p></article></div><div class="status-strip"><strong>阅读和标注继续沿用原有模块。</strong> 点击列表中的 PDF，在独立阅读页面打开。书目修改与标注修订分开，避免整理文献时影响阅读记录。</div></section>
<section id="screens"><h2>三栏界面与实际检索结果</h2><p class="intro">左侧选择视图和条件，中间查看结果，右侧查看或编辑书目信息。下面的组合检索截图来自隔离测试库，测试题名和作者是验收字段，不代表对应论文的真实书目信息。</p><figure class="proof"><img src="@@QUERY_IMAGE@@" alt="新文献库按作者、期刊、年份、标签组合筛选，显示智能集合和文献详情"><figcaption>组合检索与智能集合：作者任一匹配，年份 2024—2025，期刊按别名归一，同时要求两个标签。新增匹配条目后集合自动更新。</figcaption></figure><figure class="proof"><img src="@@DOI_IMAGE@@" alt="DOI 候选字段对比，已填写的题名、作者和日期未被默认勾选覆盖"><figcaption>真实 DOI 查询的候选对比：已有题名、作者、出版日期保持不变；勾选字段只进入草稿，保存由你确认。</figcaption></figure><figure class="proof"><img src="@@PRIMARY_IMAGE@@" alt="升级后的真实主资料库显示 34 条现有文献，仍保持待核对和待补全状态"><figcaption>升级后的真实主库。原有记录保留，未知作者、年份和期刊继续标为待补全；没有把测试数据或猜测信息填进主库。</figcaption></figure></section>
<section id="data"><h2>升级前后，已有数据保持一致</h2><p class="intro">升级前自动生成 SQLite 备份，随后逐表比较原有字段内容摘要，并核对管理副本的 SHA-256。资料库完整性检查结果为 ok。</p><div class="table-wrap"><table><thead><tr><th>数据</th><th>升级前</th><th>升级后</th><th>校验结果</th></tr></thead><tbody>@@ROWS@@</tbody></table></div><div class="note">34 / 34 个附件文件的哈希一致。备份文件位于 data/workspace/backups，具体路径和逐表结果见升级校验 JSON。完整备份仍应先停止程序，再复制整个资料库目录。</div><div class="links"><a href="../stage2-primary-upgrade.json">主库升级与完整性记录 ↗</a><a href="../stage2-reader-preservation.json">既有标注与阅读器导出保留检查 ↗</a></div></section>
<section id="quality"><h2>验证覆盖了日常操作和容易丢数据的边界</h2><div class="checklist"><article class="check"><span class="pass">通过</span><strong>编辑与组合筛选</strong><p>通过真实界面新建条目，检验作者并集、年份区间，以及作者/期刊/年份/标签交集。Nb₅Si₃ 的显示保留科学下标，普通字符搜索也能命中。</p></article><article class="check"><span class="pass">通过</span><strong>智能集合与批量操作</strong><p>保存条件后重载页面，集合仍在；新增匹配条目自动出现。批量修改、CSL-JSON 下载、移入回收站和恢复均已实际执行。</p></article><article class="check"><span class="pass">通过</span><strong>编辑冲突和草稿</strong><p>第二客户端更新后，旧编辑器无法覆盖新内容；未保存草稿可在重载后恢复。两个页签的草稿分别保留，不相互替换。</p></article><article class="check"><span class="pass">通过</span><strong>快速检索时序</strong><p>人为延迟旧检索响应，再输入新条件，确认旧响应不会把新查询和结果覆盖回去。</p></article><article class="check"><span class="pass">通过</span><strong>候选字段保护</strong><p>已填写的题名、作者和出版日期不会默认被覆盖；查询和应用候选都不会自动保存。真实公开 DOI 的 Crossref 连接已验证。</p></article><article class="check"><span class="pass">通过</span><strong>导入及阅读回归</strong><p>首次导入新增 1 条文献和附件；重复导入不再增加。受控文件夹新增 1、去重 1、排除生成文件 1。书目修改后，原有 6 条标注和 PDF 导出正常。</p></article></div><div class="links"><a href="../stage2-tests-final.log">@@TESTS@@ 项基础测试日志 ↗</a><a href="../stage2-ui-flow.json">完整界面流程结果 ↗</a><a href="../stage2-ui-safety.json">冲突、草稿与候选保护 ↗</a><a href="../stage2-draft-isolation.json">双页签草稿隔离 ↗</a><a href="../stage2-ui-directory.json">目录导入实际结果 ↗</a><a href="../stage2-reader-regression.json">独立阅读器回归 ↗</a></div></section>
<section id="extension"><h2>给后续参考文献插入保留了清楚的接入位置</h2><div class="architecture"><div><span class="pill">本阶段已落实</span><h3>结构化书目与稳定 ID</h3><p>有序作者、发表日期、期刊、DOI 等独立保存；文献、附件、标注各有稳定 ID。导出 CSL-JSON，未知字段与作者扩展信息保留。</p></div><div><span class="pill">接口已定义</span><h3>CitationFormatter</h3><p>后续接入成熟 CSL 处理器，负责样式、引文簇、页码与参考文献表。显示编号不会成为数据主键。</p></div><div><span class="pill">后续实现</span><h3>WritingConnector</h3><p>再按实际使用的 Word、WPS 等工具实现连接器，插入可更新的引用标记并处理增删后的编号刷新。</p></div></div><p class="small" style="margin-top:18px">本轮没有实现 Word/WPS 插件。文献库、存储、元数据来源、阅读器和界面分别封装；上游阅读组件的固定提交保持不变。</p><h3 style="margin:28px 0 12px">建议你先这样试用</h3><ol class="steps"><li>打开一条现有文献，在右侧编辑作者、年份、期刊；有 DOI 时可以取得候选。</li><li>保存后，在左侧同时选择作者、年份区间与期刊，检查结果。</li><li>把常用组合保存为智能集合，再导入一份新 PDF 体验自动归入。</li><li>点击 PDF 阅读与标注，用完后通过“停止文献工作台.cmd”结束服务。</li></ol><details open><summary>这一版仍有哪些边界？</summary><p>当前是本地浏览器版本，桌面安装包尚未制作。文献库搜索覆盖元数据和文件名，未建立全库 PDF 正文索引；OCR、密码 PDF、编辑已有内嵌标注、任意嵌套布尔表达式和跨设备同步尚未实现。已有文件的书目信息仍需核对，DOI 来源目前仅接入 Crossref。</p></details><details><summary>怎样启动、停止和复现测试？</summary><p>双击工程目录中的“启动文献工作台.cmd”，默认打开 http://127.0.0.1:4178；停止使用“停止文献工作台.cmd”。原入口保留兼容。npm test 可运行基础测试；浏览器验收脚本及隔离库说明见 README 和 PHASE2.md。</p></details><div class="links"><a href="../../README.md">使用与启动说明 ↗</a><a href="../../PHASE2.md">第二阶段功能、边界与模块 ↗</a><a href="../../ARCHITECTURE.md">架构与未来写作引用设计 ↗</a><a href="../phase-2-summary.json">交付汇总 JSON ↗</a></div></section><footer class="foot"><strong>本地文献工作台 · 第二阶段完成</strong><br>验证日期：2026 年 10 月 30 日（Asia/Shanghai）。核心功能在本机运行，只有手动 DOI 候选查询需要连接 <a href="https://www.crossref.org/documentation/retrieve-metadata/rest-api/">Crossref</a>。本轮未公开发布软件，也未向外部服务上传论文。</footer></main></body></html>'''
